"use client";

import { useMemo, useState } from "react";
import { historicalFigures } from "@/data/historical-figures";
import {
  defaultTimeTheaterSelection,
  timeTheaterCastIds,
  timeTheaterScripts,
  timeTheaterTopics,
} from "@/data/time-theater";
import { cn } from "@/lib/cn";
import { Panel } from "@/components/ui/panel";
import { PlaceholderArt } from "@/components/ui/placeholder-art";

export function TimeTheaterDemo() {
  const cast = useMemo(
    () =>
      historicalFigures.filter((figure) => timeTheaterCastIds.includes(figure.id)),
    [],
  );

  const [selectedIds, setSelectedIds] = useState(defaultTimeTheaterSelection);
  const [viewpointId, setViewpointId] = useState(defaultTimeTheaterSelection[0]);
  const [topicId, setTopicId] = useState(timeTheaterTopics[0]?.id ?? "");
  const [progress, setProgress] = useState(1);

  const selectedCast = cast.filter((figure) => selectedIds.includes(figure.id));
  const activeTopic =
    timeTheaterTopics.find((topic) => topic.id === topicId) ?? timeTheaterTopics[0];
  const stageReady =
    !!activeTopic &&
    activeTopic.requiredSpeakerIds.every((speakerId) => selectedIds.includes(speakerId));
  const script = activeTopic ? timeTheaterScripts[activeTopic.id] ?? [] : [];
  const selectedViewpoint =
    selectedCast.find((figure) => figure.id === viewpointId) ?? selectedCast[0] ?? null;
  const effectiveViewpointId = selectedViewpoint?.id ?? "";
  const displayProgress = Math.min(progress, Math.max(script.length, 1));
  const visibleLines = script.slice(0, displayProgress);

  const toggleCharacter = (figureId: string) => {
    setProgress(1);
    setSelectedIds((current) => {
      if (current.includes(figureId)) {
        if (current.length === 1) {
          return current;
        }

        return current.filter((id) => id !== figureId);
      }

      if (current.length >= 3) {
        return current;
      }

      return [...current, figureId];
    });
  };

  return (
    <div className="grid gap-6 xl:grid-cols-[0.95fr_1.35fr]">
      <div className="space-y-6">
        <Panel className="p-6">
          <div className="space-y-5">
            <div>
              <p className="text-xs uppercase tracking-[0.3em] text-amber-200/70">
                第一步
              </p>
              <h2 className="mt-3 font-display text-3xl text-stone-50">
                选择同台人物
              </h2>
              <p className="mt-3 text-sm leading-7 text-stone-300">
                当前试玩支持最多选择 3 位角色同台。这个限制是为了先把舞台骨架和状态切换做稳定，后续可以继续扩展到更多人。
              </p>
            </div>

            <div className="grid gap-3">
              {cast.map((figure) => {
                const active = selectedIds.includes(figure.id);

                return (
                  <button
                    key={figure.id}
                    type="button"
                    onClick={() => toggleCharacter(figure.id)}
                    className="w-full text-left"
                  >
                    <Panel
                      className={cn(
                        "p-4 transition-colors",
                        active
                          ? "border-amber-200/25 bg-amber-100/8"
                          : "hover:border-white/20",
                      )}
                    >
                      <div className="flex items-center gap-4">
                        <div className="flex h-12 w-12 items-center justify-center rounded-2xl border border-white/10 bg-white/5 font-display text-lg text-stone-50">
                          {figure.portraitLabel}
                        </div>
                        <div>
                          <p className="font-display text-2xl text-stone-50">
                            {figure.name}
                          </p>
                          <p className="text-sm text-stone-400">
                            {figure.dynasty} · {figure.role}
                          </p>
                        </div>
                      </div>
                    </Panel>
                  </button>
                );
              })}
            </div>
          </div>
        </Panel>

        <Panel className="p-6">
          <div className="space-y-4">
            <div>
              <p className="text-xs uppercase tracking-[0.3em] text-amber-200/70">
                第二步
              </p>
              <h2 className="mt-3 font-display text-3xl text-stone-50">
                设定第一视角与话题
              </h2>
            </div>

            <div>
              <p className="mb-3 text-sm text-stone-400">第一视角</p>
              <div className="flex flex-wrap gap-3">
                {selectedCast.map((figure) => (
                  <button
                    key={figure.id}
                    type="button"
                    onClick={() => {
                      setViewpointId(figure.id);
                      setProgress(1);
                    }}
                    className={cn(
                      "rounded-full border px-4 py-2 text-sm transition-colors",
                      effectiveViewpointId === figure.id
                        ? "border-amber-200/40 bg-amber-100/12 text-amber-50"
                        : "border-white/10 bg-white/5 text-stone-300 hover:text-stone-50",
                    )}
                  >
                    {figure.name}
                  </button>
                ))}
              </div>
            </div>

            <div>
              <p className="mb-3 text-sm text-stone-400">讨论话题</p>
              <div className="space-y-3">
                {timeTheaterTopics.map((topic) => {
                  const available = topic.requiredSpeakerIds.every((speakerId) =>
                    selectedIds.includes(speakerId),
                  );

                  return (
                    <button
                      key={topic.id}
                      type="button"
                      onClick={() => {
                        setTopicId(topic.id);
                        setProgress(1);
                      }}
                      className={cn(
                        "w-full rounded-[20px] border p-4 text-left transition-colors",
                        topicId === topic.id
                          ? "border-amber-200/30 bg-amber-100/10"
                          : "border-white/10 bg-white/5 hover:border-white/20",
                      )}
                    >
                      <div className="flex flex-wrap items-center justify-between gap-3">
                        <p className="text-base text-stone-100">{topic.title}</p>
                        <span
                          className={cn(
                            "rounded-full px-3 py-1 text-xs",
                            available
                              ? "border border-emerald-200/25 bg-emerald-100/8 text-emerald-100"
                              : "border border-white/10 bg-black/20 text-stone-400",
                          )}
                        >
                          {available ? "可开演" : "需补齐人物"}
                        </span>
                      </div>
                      <p className="mt-3 text-sm leading-7 text-stone-400">
                        {topic.description}
                      </p>
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        </Panel>
      </div>

      <div className="space-y-6">
        <Panel className="p-6">
          <div className="grid gap-5 lg:grid-cols-[1.15fr_0.85fr]">
            <div className="space-y-4">
              <p className="text-xs uppercase tracking-[0.3em] text-amber-200/70">
                第三步
              </p>
              <h2 className="font-display text-3xl text-stone-50">
                进入跨时空互动剧场
              </h2>
              <p className="text-sm leading-7 text-stone-300">
                当前版本先用预设话题和对白做舞台雏形。后续接入 AI 后，可以让同一组选角在同一主题下产生更多即兴互动。
              </p>
            </div>
            <PlaceholderArt
              label="剧"
              caption="舞台占位图：灯光、长桌与跨时代同台的仪式感"
              tone="jade"
              className="min-h-[240px]"
            />
          </div>
        </Panel>

        <Panel className="p-6">
          <div className="space-y-5">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <div>
                <p className="text-sm text-stone-400">互动剧场区</p>
                <p className="mt-2 text-lg text-stone-100">
                  当前视角：{selectedViewpoint?.name ?? "未选择"} · 话题：
                  {activeTopic?.title ?? "未选择"}
                </p>
              </div>
              <button
                type="button"
                onClick={() => setProgress(1)}
                className="rounded-full border border-white/10 px-4 py-2 text-sm text-stone-300 transition hover:text-stone-50"
              >
                从开场重看
              </button>
            </div>

            {stageReady && activeTopic ? (
              <div className="rounded-[24px] border border-white/10 bg-black/15 p-5 text-sm leading-7 text-stone-300">
                {activeTopic.opening}
              </div>
            ) : (
              <div className="rounded-[24px] border border-white/10 bg-black/15 p-5 text-sm leading-7 text-stone-300">
                当前所选人物还不足以撑起这个话题，请先在左侧补齐所需角色。
              </div>
            )}

            {stageReady ? (
              <div className="space-y-4">
                {visibleLines.map((line, index) => {
                  const speaker = cast.find((figure) => figure.id === line.speakerId);

                  return (
                    <div
                      key={`${line.speakerId}-${index}`}
                      className="rounded-[24px] border border-white/10 bg-black/15 p-5"
                    >
                      <div className="flex items-start gap-4">
                        <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl border border-white/10 bg-white/5 font-display text-lg text-stone-50">
                          {speaker?.portraitLabel ?? "剧"}
                        </div>
                        <div>
                          <div className="flex flex-wrap items-center gap-3">
                            <p className="font-medium text-stone-100">
                              {speaker?.name ?? "匿名角色"}
                            </p>
                            {speaker?.id === effectiveViewpointId ? (
                              <span className="rounded-full border border-amber-200/25 px-3 py-1 text-xs text-amber-50">
                                你的当前视角
                              </span>
                            ) : null}
                          </div>
                          <p className="mt-3 text-sm leading-7 text-stone-300">
                            {line.text}
                          </p>
                        </div>
                      </div>
                    </div>
                  );
                })}

                {progress < script.length ? (
                  <button
                    type="button"
                    onClick={() =>
                      setProgress((current) => Math.min(current + 1, script.length))
                    }
                    className="rounded-full border border-amber-200/25 bg-amber-100/10 px-5 py-3 text-sm text-amber-50 transition hover:border-amber-200/40 hover:bg-amber-100/15"
                  >
                    继续观看对白
                  </button>
                ) : (
                  <div className="rounded-[24px] border border-emerald-200/20 bg-emerald-100/8 p-5 text-sm leading-7 text-stone-200">
                    这一轮跨时空互动已经播完。当前版本完成了人物选择、第一视角切换、话题切换和对白推进的试玩骨架。
                  </div>
                )}
              </div>
            ) : null}
          </div>
        </Panel>
      </div>
    </div>
  );
}
